mapper.select:
WITH candidates AS (
SELECT CAST(#{idx} AS DECIMAL(10, 0)) AS candidate_index , CONCAT(#{code}, '') AS company_code
)
, matching_candidates AS ( SELECT DISTINCT c.candidate_index FROM candidates c INNER JOIN ip_pool_status ips ON ips.security_code = c.company_code WHERE ips.security_type = 'company' AND ips.target_pool_id IN (#{forbiddenPoolId}, #{keyWatchPoolId}) AND ips.audit_status = '20' AND ips.is_deleted = 0
UNION SELECT c.candidate_index FROM candidates c INNER JOIN ais_inv_ods.wind_cbondissuerrating r ON r.s_info_compcode = c.company_code WHERE r.b_info_creditratingagency IN
#{agencyCode}
AND r.ann_dt >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 YEAR), '%Y%m%d') AND REGEXP_SUBSTR(TRIM(r.b_info_creditrating), '^(A+|B+|C+|D)[+-]?', 1, 1, 'c') IN ( 'AA-', 'A+', 'A', 'A-' , 'BBB+', 'BBB', 'BBB-' , 'BB+', 'BB', 'BB-' , 'B+', 'B', 'B-' , 'CCC', 'CC', 'C', 'D' )
)
SELECT c.company_code FROM candidates c INNER JOIN matching_candidates hit ON hit.candidate_index = c.candidate_index

SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM ip_pool_status ips
    WHERE ips.security_code = #{companyCode}
      AND ips.security_type = 'company'
      AND ips.target_pool_id = #{poolId}
      AND ips.audit_status = '20'
      AND ips.is_deleted = 0
) THEN 1 ELSE 0 END

SELECT CASE WHEN EXISTS ( SELECT 1 FROM ais_inv_ods.wind_cbondissuerrating r WHERE r.s_info_compcode = #{companyCode}
AND r.b_info_creditratingagency IN
#{agencyCode}
AND 1 = 0
AND r.ann_dt >= DATE_FORMAT(DATE_SUB(CURDATE(), INTERVAL 1 YEAR), '%Y%m%d') AND REGEXP_SUBSTR(TRIM(r.b_info_creditrating), '^(A+|B+|C+|D)[+-]?', 1, 1, 'c') IN ( 'AA-', 'A+', 'A', 'A-' , 'BBB+', 'BBB', 'BBB-' , 'BB+', 'BB', 'BB-' , 'B+', 'B', 'B-' , 'CCC', 'CC', 'C', 'D' ) ) THEN 1 ELSE 0 END
